"""Build the English research-path page from catalog.json and resource provenance."""
from pathlib import Path
from html import escape
import json
ROOT=Path(__file__).resolve().parents[1]
docs=ROOT/'docs'
catalog=json.loads((docs/'catalog.json').read_text())
resources=json.loads((docs/'microphysics/resources.json').read_text())
parts=['''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Research paths · The Art of Thermal Instability</title><meta name="description" content="From FGH to Wolfire and GOW chemistry, and from phase-transition fronts to magnetized clouds: a growing reading list and realistic computational scope."><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="field-1965/exhibit.css"></head>
<body><header><a class="brand" href="./">The Art of Thermal Instability</a><nav aria-label="Research paths"><a href="./#atlas">All papers by year</a><a href="#theory">Theory</a><a href="#rate-history">Rate history</a><a href="#microphysics">Modern rates</a><a href="#cloud-formation">Cloud formation</a><a href="#inoue">Inoue</a><a href="#iwasaki">Iwasaki</a><a href="#fronts">Fronts</a></nav></header><main class="exhibit">
<section class="hero"><p class="eyebrow">Research paths / Reading list</p><h1>From two phases<br>to chemistry and cloud formation.</h1><p class="intro">FGH established a two-phase picture. Later work changed the heating and chemical inputs, then followed fronts, turbulence, and magnetized clouds. This reading list connects those questions to the calculations we can document and explore.</p><p class="notice">Listed references are not completed reproductions. Bibliography and abstracts have been checked; equations, target figures, and data availability need individual review. This page groups papers by research path; each path runs from oldest to newest. For one chronological list across all paths, open <a href="./#atlas">all papers by year</a>. Publication years are used where confirmed, with preprint dates noted separately.</p></section>
<section id="scope"><p class="eyebrow">Scope for modern simulations</p><h2>Choose the scientific question before the computing budget.</h2><p>Reproducing a large multidimensional simulation can require substantial computing time, storage, and access to original inputs. Our modern-paper exhibits can instead provide a source guide, documented setup, analysis of available outputs, or a small benchmark that isolates a physical mechanism.</p><ul><li><strong>Source and method:</strong> link the paper and any public code, inputs, and datasets; record what is actually available.</li><li><strong>Reuse and analysis:</strong> regenerate a diagnostic from released outputs where possible, preserving units, provenance, and processing steps.</li><li><strong>Small calculations:</strong> evaluate an analytic relation, a one-zone chemical model, a front, or a convergence test within an explicit reduced scope.</li><li><strong>Optional full runs:</strong> record the resolution, solver, hardware, wall time, and storage needed. A full 2D/3D rerun is not a condition for completing a source or analysis exhibit.</li></ul><p>For new nonlinear thermal-instability simulation exhibits, the thermal-conduction treatment and resolution of its relevant scales are selection criteria to audit explicitly. Analytical theory and microphysical rate references are documented separately. Digitized published curves will be identified as digitizations. Reduced models will state their omissions; their results will not be labeled as full-simulation reproductions.</p></section>''']
for section,title,intro in [
 ('theory','Foundations: thermal stability and conductive phase exchange','Parker (1953) provides a pre-Field historical starting point. Balbus (1986) extends the local stability analysis to evolving backgrounds, while Begelman & McKee (1990) treats conductive mass exchange between phases. Analytical background references and conduction-resolved simulation exhibits have different roles.'),
 ('rate-history','Rate-coefficient lineage: the earlier sources','A separate branch follows the atomic and molecular data, radiative yields, and heating/cooling prescriptions behind gas models. These papers are not all chemical-network rate catalogs.'),
 ('microphysics','Heating, cooling, and public chemistry','Cosmic-ray heating in FGH, grain photoelectric heating in Bakes & Tielens (1994), Wolfire (1995, 2003), and GOW (2017) provide a path to public chemistry implementations. These models use different physical assumptions; they are not interchangeable cooling prescriptions.'),
 ('fronts','Phase-transition fronts: from planar balance to curved clouds','Zel’dovich–Pikel’ner (1969) and Penston–Brown (1970) connect to Elphick–Regev–Shaviv (1992), Ferrara–Shchekinov (1993), Shchekinov–Ibáñez (2001), Nagashima and collaborators’ curved-front work, and Kim & Kim’s (2013) conductive evaporation-front instability. Static balance, steady mass flux, perturbations, and spherical survival times are distinct computational questions.'),
 ('cloud-formation','Hennebelle, Burkert, and collaborators: condensation and fragmentation','Converging flows connect thermal bistability to cloud formation. Hennebelle and collaborators examine dynamical condensation, magnetic fields, and turbulent two-phase gas; Burkert and collaborators examine cooling perturbations, colliding flows, and fragmentation. These are related research paths, not a claim that the listed papers share the same authors or physical model.'),
 ('inoue','Inoue: fronts, two-fluid gas, and magnetic fields','A path from the stability of phase-transition fronts to converging flows and turbulent molecular clouds.'),
 ('iwasaki','Iwasaki: condensation, interfaces, and cloud formation','Similarity solutions and front structure offer modest-cost entry points. Later multidimensional calculations can be explored through their diagnostics and available data.')]:
    parts.append(f'<section id="{section}"><p class="eyebrow">Reading path</p><h2>{escape(title)}</h2><p>{escape(intro)}</p>')
    for p in sorted(catalog,key=lambda item:item['year']):
        if p.get('reference_section')!=section:continue
        state='Computed prototype / technical review pending' if p['status']=='prototype' else 'Source rates audited / truncated model' if p['status']=='audited' else 'Reference listed'
        publication_link=f'<a href="https://doi.org/{escape(p["doi"])}" target="_blank" rel="noopener noreferrer">Publication / DOI ↗</a>' if p.get('doi') else ''
        exhibit_links=''.join(f'<a href="{escape(e["href"])}">{escape(e["label"])}</a>' for e in p.get('exhibits',[]))
        parts.append(f'''<article id="{p['id']}"><p class="eyebrow">{p['year']} / {state}</p><h3>{escape(p['title'])}</h3><p class="small">{escape(p['authors'])}<br>{escape(p['journal'])}</p><p>{escape(p['topic'])}</p><p><strong>Proposed scope:</strong> {escape(p['scope'])}</p><div class="downloads"><a href="{escape(p['source'])}" target="_blank" rel="noopener noreferrer">Paper &amp; abstract ↗</a>{publication_link}{exhibit_links}</div></article>''')
    if section=='rate-history':
        parts.append('<p>Field et al. (1968) discusses Takayanagi and Nishimura’s H₂ excitation data. FGH (1969) cites Hayakawa, Nishimura and Takayanagi’s cosmic-ray heating work. Hattori, Nakano and Hayashi’s reference list includes both papers. These links identify a route for source tracing; they do not establish that later models use identical coefficients.</p><p>For each future rate record, we will distinguish cross sections, rate coefficients, energy-loss coefficients, volumetric rates, and yields. Species, colliders, units, normalization, validity range, population assumptions, source equation/table, and correction/code version will accompany the numerical formula.</p><p class="notice">The <a href="takayanagi-nishimura-1960/">Takayanagi–Nishimura rate audit</a> now transcribes 34 coefficients and tests a finite level model. Its Table 2 mismatches remain visible. Other coefficient sets still require equation/table review; the citation links alone do not validate them. <a href="microphysics/lineage.json">Lineage evidence and proposed coefficient-record fields / JSON</a></p>')
    if section=='cloud-formation':
        parts.append('<p>Publication years determine the order: Audit &amp; Hennebelle (2005) has a 2004 preprint, and Hennebelle &amp; Audit (2007) has a 2006 preprint. For modest computing budgets, the self-similar, perturbation-growth, semi-analytical, and timescale arguments offer entry points. High-resolution multidimensional statistics require suitable released outputs or a separately documented computing plan.</p>')
    if section=='fronts':
        parts.append('<p><strong>Gradient-flow connection:</strong> <a href="#elphick-1992">Elphick, Regev &amp; Shaviv (1992)</a> gives an isobaric reduction in Lagrangian mass coordinates, a Lyapunov functional, equal-minima ZP fronts and front interactions. The <a href="essays/biophysical-fronts.html">biophysical comparisons</a> follow wave-pinning, conserved protein redistribution and neural excitability, with their distinct conservation laws and scope.</p>')
        parts.append('<p><strong>Conductive front instability:</strong> <a href="#kim-kim-2013">Kim &amp; Kim (2013)</a> explicitly includes thermal conduction in the linear stability analysis and nonlinear evolution of evaporation fronts. This provides a comparison with <a href="#inoue-2006">Inoue et al. (2006)</a>, while <a href="#iwasaki-2012">Iwasaki &amp; Inutsuka (2012)</a> supplies a related steady-front classification. A stability spectrum, a steady-solution classification, and nonlinear saturation are different reproduction targets.</p>')
        parts.append('<p><strong>Steady flow and perturbations:</strong> Ferrara &amp; Shchekinov (1993) studies static/steady front properties and their dynamical evolution. Shchekinov &amp; Ibáñez (2001) studies planar acoustic/entropy perturbations interacting with steady subsonic fronts. In section 3, <a href="https://arxiv.org/abs/1204.5532">Iwasaki &amp; Inutsuka (2012)</a> explicitly describes the latter work as determining the ZP mass flux j(P) through an eigenvalue problem. We will audit the steady background before attempting perturbation coefficients. This citation does not establish identical cooling laws or numerical parameters.</p>')
        parts.append('<p>Related entries: <a href="#inoue-2006">Inoue, Inutsuka &amp; Koyama (2006)</a> addresses front stability; <a href="#iwasaki-2012">Iwasaki &amp; Inutsuka (2012)</a> studies dynamical condensation fronts; <a href="#iwasaki-2014">Iwasaki &amp; Inutsuka (2014)</a> studies interfacial energy transfer in a bistable medium. The <a href="https://arxiv.org/abs/astro-ph/0302126">Field-condition paper</a> provides a connection to conduction and resolution.</p><p>Different heat-loss laws, geometries, and dynamical approximations must be preserved when comparing these studies. A reading path is not proof of identical assumptions or coefficients.</p>')
    parts.append('</section>')
parts.append('''<section id="public-rates"><p class="eyebrow">GOW / Code and rate provenance</p><h2>Follow the corrected rates to their implementation.</h2><p>The GOW paper has a 2018 erratum, and Gong’s code page lists further corrections and updates. The original paper, its erratum, a revised preprint, and an evolving code repository are separate references. Before a benchmark, we will pin the actual implementation and audit its rate definitions and units.</p><p>We recorded a public PDR-code commit for reference, but have not compiled it or validated its rates. The linked code and documentation remain maintained by their authors.</p><ul>''')
for r in resources['resources']:
    parts.append(f'<li><a href="{escape(r["url"])}" target="_blank" rel="noopener noreferrer">{escape(r["id"])} ↗</a> — {escape(r["note"])}')
    if r.get('snapshot_url'):parts.append(f' <a href="{r["snapshot_url"]}" target="_blank" rel="noopener noreferrer">Recorded snapshot: {r["observed_commit"][:12]} ↗</a>')
    parts.append('</li>')
parts.append('''</ul><p class="small">Links checked on 3 November 2026. <a href="microphysics/resources.json">Resource provenance / JSON</a> · <a href="catalog.json">Complete paper catalog / JSON</a></p></section>
<section><h2>Connect these references to the current exhibits.</h2><p>The <a href="ki-2002/">corrected KI2002 equilibrium benchmark</a> includes stability branches, ZP saturation pressure and all three thermal-equilibrium intersections. <a href="equilibrium-landmarks.json">Model-specific landmarks</a> retain density conventions and unresolved cases. The <a href="essays/equal-area.html">Maxwell equal-area historical aside</a> traces the primary publications and distinguishes its integral from ZP selection. The same aside develops a <a href="essays/equal-area.html#ginzburg-landau">scalar Ginzburg–Landau connection</a>, with Elphick, Regev &amp; Shaviv (1992) as a direct precedent.</p><p><a href="field-1965/figure-1.html">Field’s stability map</a> connects to front and perturbation problems. <a href="fgh-1969/two-phase.html">FGH/GHF two-phase equilibrium prototype</a>, <a href="fgh-1969/">historical ingredients</a>, and <a href="fgh-1969/cold-branch.html">reduced cold branch</a> give a starting point for comparing historical and later microphysics.</p></section>
</main><footer><p>The Art of Thermal Instability</p><a href="./#atlas">Back to the paper atlas</a></footer></body></html>''')
(docs/'research-paths.html').write_text('\n'.join(parts)+'\n')
print('Built research paths from',sum('reference_section' in p for p in catalog),'listed references.')
